// Runs after openapi-typescript in `npm run gen:api`: puts the auto-generated marker
// first and the license header beneath it, as CLAUDE.md requires for generated files.
import { readFileSync, writeFileSync } from 'node:fs'

const path = 'src/api/schema.d.ts'
const header = [
  '// <auto-generated />',
  '// -----------------------------------------------------------------------------',
  '//  Copyright (c) NoMercy Labs.',
  '//',
  '//  This file is part of NomNomzBot, free software licensed under the GNU Affero',
  '//  General Public License v3.0 or later. You may redistribute and/or modify it',
  '//  under those terms. Distributed WITHOUT ANY WARRANTY. See LICENSE for details.',
  '//',
  '//  SPDX-License-Identifier: AGPL-3.0-or-later',
  '// -----------------------------------------------------------------------------',
  '',
  '',
].join('\n')

const body = readFileSync(path, 'utf8')
if (!body.startsWith('// <auto-generated />')) {
  writeFileSync(path, header + body)
}
